<script setup lang="ts">
import {ref,computed,nextTick,getCurrentInstance,watch} from 'vue'
import {onShow,onHide,onUnload,onPageScroll} from '@dcloudio/uni-app'
import {request,navigate,token,type Row} from '../../api/platform'
import {content} from '../../features/content'
import {contentLabel} from '../../features/catalog'
import {visibleExposure,type NativeExposureScope} from '../../features/telemetry'
import LoginSheet from '../../components/LoginSheet.vue'
import PageState from '../../components/PageState.vue'
const boxes=ref<Row[]>([]),tab=ref('CATEGORY'),grouped=ref(false),expanded=ref<string[]>([]),error=ref(''),loading=ref(false),busy=ref(false),signedIn=ref(false),revealed=ref('')
const visible=computed(()=>boxes.value.filter(b=>b.boxKind===tab.value))
const flat=computed(()=>[...new Map(visible.value.flatMap(b=>b.items).map((item:Row)=>[item.id,item])).values()])
const instance=getCurrentInstance(),exposure=visibleExposure(()=>(instance?.proxy as unknown as {$scope?:NativeExposureScope})?.$scope)
async function load(){signedIn.value=!!token();if(!signedIn.value){boxes.value=[];return}loading.value=true;error.value='';try{boxes.value=await content.boxes();await nextTick();exposure.reset();exposure.observe()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function markRead(item:Row){if(busy.value)return;busy.value=true;error.value='';try{await request('PUT','/api/v1/me/read/'+item.id,{versionId:item.currentVersionId});await load();revealed.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function expand(id:string){expanded.value=expanded.value.includes(id)?expanded.value.filter(x=>x!==id):[...expanded.value,id];void nextTick(()=>exposure.observe())}
watch([tab,grouped],()=>nextTick(()=>exposure.observe()))
let startX=0,startY=0
function touchStart(e:Row){startX=e.changedTouches?.[0]?.clientX||0;startY=e.changedTouches?.[0]?.clientY||0}
function touchEnd(e:Row,item:Row){const x=e.changedTouches?.[0]?.clientX??startX,y=e.changedTouches?.[0]?.clientY??startY;if(Math.abs(x-startX)>60&&Math.abs(y-startY)<30)revealed.value=item.id}
onShow(()=>{exposure.show();void load()});onPageScroll(()=>exposure.scroll());onHide(()=>exposure.hide());onUnload(()=>exposure.hide())
</script><template><view class="page"><view class="hero"><text class="title">信息盒子</text></view><view v-if="!signedIn" class="card"><text>登录后查看关注更新</text><button role="button" @click="navigate('login')">登录</button><button role="button" class="quiet" @click="navigate('index')">浏览资讯</button></view><template v-else><view class="actions"><button role="button" class="quiet" @click="navigate('follows')">管理关注</button><button role="button" class="quiet" @click="navigate('tag-tree')">选择推送标签</button></view><view class="segmented"><button role="button" :class="{active:tab==='CATEGORY'}" @click="tab='CATEGORY'">推送信息</button><button role="button" :class="{active:tab==='FOLLOWING'}" @click="tab='FOLLOWING'">关注更新</button><button role="button" :class="{active:tab==='REPLACEMENT'}" @click="tab='REPLACEMENT'">关注信息更替</button></view><view class="row"><text class="muted">左右滑动可标记已读；已读后从盒子移除。</text><button role="button" v-if="tab!=='REPLACEMENT'" class="quiet" @click="grouped=!grouped">{{ grouped?'改为平铺':'按关注分组' }}</button></view><PageState :busy="loading" :error="error" :empty="!flat.length&&!loading" empty-text="当前没有未读更新" @retry="load"/><template v-if="!grouped||tab==='REPLACEMENT'"><view v-for="item in flat" :key="item.id" class="card exposure-card" :data-article-id="item.id" @touchstart="touchStart" @touchend="touchEnd($event,item)"><text class="badge">{{ contentLabel(item.contentType) }}</text><text class="card-title" @click="navigate('article','?id='+item.id)">{{ item.title }}</text><text class="muted">{{ item.summary }}</text><button role="button" v-if="revealed===item.id" :disabled="busy" @click="markRead(item)">确认标记已读</button></view></template><template v-else><view v-for="box in visible" :key="box.id" class="card"><text class="card-title">{{ box.name }} · {{ box.items.length }}</text><view v-for="item in (expanded.includes(box.id)?box.items:box.items.slice(0,2))" :key="item.id" class="list-item exposure-card" :data-article-id="item.id" @touchstart="touchStart" @touchend="touchEnd($event,item)"><text @click="navigate('article','?id='+item.id)">{{ item.title }}</text><button role="button" v-if="revealed===item.id" :disabled="busy" @click="markRead(item)">标记已读</button></view><button role="button" v-if="box.items.length>2" class="quiet" @click="expand(box.id)">{{ expanded.includes(box.id)?'收起':'展开全部' }}</button></view></template></template><LoginSheet/></view></template>
